#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 1'000'000'007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, a, b, k;
    cin >> n >> a >> b >> k;

    vector<int> prev(n + 1), cur(n + 1), prefix(n + 1);

    if (a < b) {
        for (int i = 1; i < b; ++i) prev[i] = 1;
    } else {
        for (int i = b + 1; i <= n; ++i) prev[i] = 1;
    }

    for (int step = 1; step <= k; ++step) {
        prefix[0] = 0;
        for (int i = 1; i <= n; ++i) {
            prefix[i] = prefix[i - 1] + prev[i];
            if (prefix[i] >= MOD) prefix[i] -= MOD;
        }

        fill(cur.begin(), cur.end(), 0);

        int start = (a < b ? 1 : b + 1);
        int finish = (a < b ? b - 1 : n);

        for (int i = start; i <= finish; ++i) {
            int distance = abs(i - b) - 1;
            int left = max(1, i - distance);
            int right = min(n, i + distance);

            int ways = prefix[right] - prefix[left - 1];
            if (ways < 0) ways += MOD;

            ways -= prev[i];
            if (ways < 0) ways += MOD;

            cur[i] = ways;
        }

        prev.swap(cur);
    }

    cout << prev[a] << '\n';
    return 0;
}

