    const long long MOD = 1000000007LL;

    int n, a, b, k;
    cin >> n >> a >> b >> k;

    vector<long long> dp(n + 1, 0), next_dp(n + 1, 0);
    vector<long long> prefix(n + 1, 0);

    if (a < b) {
        for (int i = 1; i < b; ++i) dp[i] = 1;
    } else {
        for (int i = b + 1; i <= n; ++i) dp[i] = 1;
    }

    for (int step = 1; step <= k; ++step) {
        prefix[0] = 0;
        for (int i = 1; i <= n; ++i)
            prefix[i] = (prefix[i - 1] + dp[i]) % MOD;

        fill(next_dp.begin(), next_dp.end(), 0);

        if (a < b) {
            for (int i = 1; i < b; ++i) {
                int left = max(1, 2 * i - b + 1);
                int right = b - 1;
                long long total = (prefix[right] - prefix[left - 1] + MOD) % MOD;
                next_dp[i] = (total - dp[i] + MOD) % MOD;
            }
        } else {
            for (int i = b + 1; i <= n; ++i) {
                int left = b + 1;
                int right = min(n, 2 * i - b - 1);
                long long total = (prefix[right] - prefix[left - 1] + MOD) % MOD;
                next_dp[i] = (total - dp[i] + MOD) % MOD;
            }
        }

        dp.swap(next_dp);
    }

    cout << dp[a] << '\n';
    return 0;
}

